{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "We performed parallel review of titles, abstracts, and subsequently full texts based on updated inclusion and exclusion criteria following the population, exposure, comparison, outcome (PECO) approach\nWe included children (defined as ≤18 years old) who were attending school, and their close contacts (family and household members, teachers, school support staff). We excluded home-schooled children and their close contacts, and schools with student numbers below 20. For study outcomes, we included infections traced to a school index case with a COVID-19 positive test. We updated inclusion criteria of study types to include: 1) Cohort studies: A. Prospective cohort study: contact tracing study where the exposed contacts are followed up and secondary infections are measured.",
      "reason": "Eligibility characteristics are specified using a PECO approach, including population (children ≤18 years), exposure (school index case; traced infections), comparison (matched community described within cohort study types), outcomes (secondary infections measured), and eligible study designs (cohort, cross-sectional, pre-post). However, explicit follow-up requirements (e.g., duration/frequency for eligibility) are not fully specified in the eligibility criteria text; only that contacts are \"followed up\" is stated."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "We included articles in peer-reviewed journals and pre-prints, and excluded comments, conference abstracts and interviews.",
      "reason": "Report-characteristic eligibility is partially specified (inclusion of peer-reviewed journals and pre-prints; exclusion of comments, conference abstracts, interviews). However, dissemination year, language, and publication/report status beyond the peer-reviewed vs pre-print distinction are not reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe how the review distinguishes exclusions due to outcomes not measured versus outcomes not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "In this update we modified our inclusion criteria to include: 1) cohort studies; 2) cross-sectional studies that investigated and cross-assessed SARS-COV-2 positivity rates in schools and communities; and 3) pre-post studies.",
      "reason": "The review distinguishes eligible study group types (cohort studies; cross-sectional studies comparing schools and communities; pre-post). However, the retrieved evidence does not clearly specify how groups used in each synthesis are defined and linked to the review objectives/comparisons beyond this high-level inclusion/synthesis framing."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationales are provided in the retrieved evidence for notable restrictions on study eligibility (e.g., exclusions such as school size <20 or excluding specific study types/settings)."
    }
  ],
  "confidence": 62
}

